// Domain types for the OKRs module.
//
// These live here rather than in src/types/database.ts because that file is
// generated by `supabase gen types` and must never be hand-edited. The service
// layer is untyped (`type Client = any`, as in src/services/ministries.ts), so
// these describe the shapes the pages and components actually pass around.

export const OKR_STATUSES = [
  "not_started",
  "in_progress",
  "moving_forward",
  "stuck",
  "complete",
] as const;

export type OkrStatus = (typeof OKR_STATUSES)[number];

export type OkrScope = "ministry" | "individual";

export interface OkrCycle {
  id: string;
  name: string;
  slug: string;
  starts_on: string;
  ends_on: string;
  is_current: boolean;
}

export interface OkrKeyResult {
  id: string;
  objective_id: string;
  position: number;
  label: string | null;
  description: string;
  notes: string | null;
  timeline: string | null;
  owner_note: string | null;
  metric_unit: string | null;
  metric_start: number | null;
  metric_target: number | null;
  current_status: OkrStatus;
  current_value: number | null;
  last_checkin_at: string | null;
}

export interface OkrObjective {
  id: string;
  cycle_id: string;
  scope: OkrScope;
  staff_ministry_id: string;
  subcategory_id: string | null;
  owner_user_id: string | null;
  position: number;
  title: string;
  description: string | null;
  owner_note: string | null;
  timeline: string | null;
  is_archived: boolean;
  okr_key_results: OkrKeyResult[];
}

export interface OkrCheckin {
  id: string;
  key_result_id: string;
  checkin_on: string;
  status: OkrStatus;
  value: number | null;
  comment: string | null;
  author_id: string;
  created_at: string;
  /** Hydrated separately via the admin client — see the users-RLS note. */
  author_name?: string | null;
}

/** Per-ministry roll-up for the OKR wall. */
export interface MinistryOkrSummary {
  staff_ministry_id: string;
  name: string;
  slug: string;
  objectives: number;
  keyResults: number;
  byStatus: Record<OkrStatus, number>;
}
